package app.gboardios.patches.shared

import app.morphe.patcher.patch.ResourcePatchContext
import org.w3c.dom.Element

/**
 * Gboard ships with obfuscated resource names, so the decoded names are generated by the decoder
 * and may differ between tools. Resources are therefore addressed by their ids, which are fixed
 * for the supported Gboard build, and translated to the decoded names through `public.xml`.
 */
class ResourceIds private constructor(private val names: Map<Long, Pair<String, String>>) {

    /** `@type/name` reference for [id]. */
    fun ref(id: Long): String = entry(id).let { (type, name) -> "@$type/$name" }

    /** Decoded file path of a file resource such as a layout or an xml, in the default configuration. */
    fun path(id: Long): String = entry(id).let { (type, name) -> "res/$type/$name.xml" }

    /**
     * Replaces placeholders of the form `{{0x7f0e0701}}` with the decoded reference of that id,
     * so XML bundled with the patches can refer to obfuscated resources.
     */
    fun expand(text: String): String = PLACEHOLDER.replace(text) { match ->
        ref(match.groupValues[1].removePrefix("0x").toLong(16))
    }

    private fun entry(id: Long) = names[id] ?: error("Resource 0x${id.toString(16)} is missing from public.xml")

    companion object {
        private val PLACEHOLDER = Regex("""\{\{(0x[0-9a-fA-F]{8})}}""")

        fun read(context: ResourcePatchContext): ResourceIds {
            val names = HashMap<Long, Pair<String, String>>()
            context.document("res/values/public.xml").use { document ->
                val publics = document.getElementsByTagName("public")
                for (i in 0 until publics.length) {
                    val element = publics.item(i) as Element
                    val id = element.getAttribute("id").removePrefix("0x").toLongOrNull(16) ?: continue
                    names[id] = element.getAttribute("type") to element.getAttribute("name")
                }
            }
            return ResourceIds(names)
        }
    }
}
